package com.aoo.bcg.common.cache;
import java.time.Duration;import java.util.List;import java.util.Objects;
/** Atomic copy-with-remaining-TTL then delete-old. Both keys must share a Redis Cluster hash tag. */
public final class RedisAtomicKeyMigration{public static final String LUA="if redis.call('EXISTS',KEYS[2])==1 then return 0 end local payload=redis.call('DUMP',KEYS[1]) if not payload then return -1 end local ttl=redis.call('PTTL',KEYS[1]) if ttl==-1 then ttl=tonumber(ARGV[1]) end if ttl<=0 then return -2 end redis.call('RESTORE',KEYS[2],ttl,payload) redis.call('DEL',KEYS[1]) return 1";public static final RedisLuaContract CONTRACT=new RedisLuaContract("atomic-key-migration",2,true,Duration.ofMillis(100),RedisLuaContract.ResultType.INTEGER,java.util.Set.of("prod:","staging:","test:"));private final RedisScriptExecutor executor;public RedisAtomicKeyMigration(RedisScriptExecutor executor){this.executor=Objects.requireNonNull(executor);}public long migrate(String source,String target,Duration persistentCap){List<String>keys=List.of(source,target);CONTRACT.validate(keys);return executor.eval(LUA,keys,List.of(Long.toString(persistentCap.toMillis())));} }
